// Compiles the AI trading engine (the SAME TypeScript the app runs in the browser) into plain ES modules for the backend,
// so the server-side runner and the browser can never drift apart. Run it after changing any engine file:
//     npm run build:runner
// Output: backend/src/runner/engine/*.js (generated: do not edit; edit the .ts files and rebuild).
import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ts = require('typescript');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const bt = path.join(root, 'src/pages/bulk-trader');
const out = path.join(root, 'backend/src/runner/engine');

const FILES = [
    [path.join(bt, 'autoPilotEngine.ts')],
    [path.join(bt, 'derivClient.ts')],
    [path.join(bt, 'learningEngine.ts')],
    [path.join(bt, 'contractRules.ts')],
    [path.join(bt, 'tradingKnowledge.ts')],
    [path.join(bt, 'trendFilter.ts')],
    [path.join(bt, 'contractSpecs.ts')],
    [path.join(bt, 'paperStats.ts')],
    [path.join(bt, 'runBias.ts')],
    [path.join(root, 'src/pages/journal/selfReview.ts')],
];
// Browser-only modules are replaced by Node versions that live next to the output (hand-written, not generated).
const REWRITE = new Map([
    ['@/services/derivws-accounts.service', './derivws-accounts.service.js'],
    ['./headerBalance', './headerBalance.js'],
    ['../journal/selfReview', './selfReview.js'],
]);

const check = process.argv.includes('--check'); // compare instead of write: fails if the compiled copy is out of date
fs.mkdirSync(out, { recursive: true });
let problems = 0;
let stale = 0;
for (const [file] of FILES) {
    const source = fs.readFileSync(file, 'utf8');
    const result = ts.transpileModule(source, {
        fileName: file,
        reportDiagnostics: true,
        compilerOptions: { module: ts.ModuleKind.ES2022, target: ts.ScriptTarget.ES2022 },
    });
    for (const d of result.diagnostics ?? []) {
        problems += 1;
        console.error(`${path.basename(file)}: ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`);
    }
    const code = result.outputText.replace(/(from\s+|import\s*\()\s*['"]([^'"]+)['"]/g, (m, lead, spec) => {
        const mapped = REWRITE.get(spec) ?? (spec.startsWith('./') && !spec.endsWith('.js') ? `${spec}.js` : spec);
        return `${lead}'${mapped}'`;
    });
    const header = `// GENERATED by scripts/build-runner.mjs from ${path.relative(root, file)}. Do not edit: change the .ts file and rebuild.\n`;
    const target = path.join(out, path.basename(file).replace(/\.ts$/, '.js'));
    if (check) {
        if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== header + code) {
            stale += 1;
            console.error(`${path.basename(target)} is out of date: run npm run build:runner`);
        }
    } else {
        fs.writeFileSync(target, header + code);
    }
}
if (check) {
    console.log(stale ? `${stale} compiled engine file(s) out of date` : 'compiled engine is up to date');
    process.exit(stale || problems ? 1 : 0);
}
console.log(problems ? `${problems} problem(s)` : `built ${FILES.length} engine files into backend/src/runner/engine`);
process.exit(problems ? 1 : 0);
